{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required field')
    nodes = case['nodes']
    required = case['required_symbols']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a nonempty array')
    if not isinstance(required, list) or any(not isinstance(s, str) for s in required):
        raise ValueError('required_symbols must be an array of strings')
    if len(set(required)) != len(required):
        raise ValueError('duplicate required symbol')

    required_fields = ('id', 'parent', 'symbol', 'depth', 'removable', 'utility')
    by_id = {}
    for node in nodes:
        if not isinstance(node, dict) or any(key not in node for key in required_fields):
            raise ValueError('invalid node')
        node_id = node['id']
        parent = node['parent']
        depth = node['depth']
        utility = node['utility']
        if not isinstance(node_id, str) or not isinstance(node['symbol'], str):
            raise ValueError('node id and symbol must be strings')
        if parent is not None and not isinstance(parent, str):
            raise ValueError('parent must be null or a string')
        if type(depth) is not int or depth < 0:
            raise ValueError('depth must be a nonnegative integer')
        if type(node['removable']) is not bool:
            raise ValueError('removable must be boolean')
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('utility must be finite')
        if node_id in by_id:
            raise ValueError('duplicate node id')
        by_id[node_id] = node

    roots = [node for node in nodes if node['parent'] is None]
    if len(roots) != 1:
        raise ValueError('tree must have exactly one root')
    root_id = roots[0]['id']
    if roots[0]['depth'] != 0:
        raise ValueError('root depth must be zero')

    children = {node_id: set() for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node['parent']
        if parent is not None:
            if parent not in by_id or parent == node_id:
                raise ValueError('invalid parent')
            children[parent].add(node_id)

    seen = set()
    stack = [(root_id, 0)]
    while stack:
        node_id, expected_depth = stack.pop()
        if node_id in seen or by_id[node_id]['depth'] != expected_depth:
            raise ValueError('invalid tree depth or cycle')
        seen.add(node_id)
        for child_id in children[node_id]:
            stack.append((child_id, expected_depth + 1))
    if len(seen) != len(by_id):
        raise ValueError('tree is disconnected or cyclic')

    represented = {node['symbol'] for node in nodes}
    if not set(required).issubset(represented):
        raise ValueError('required symbol is absent')

    active_children = {node_id: set(child_ids) for node_id, child_ids in children.items()}
    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node['depth'], node['id']))
    for node in candidates:
        node_id = node['id']
        if (not node['removable'] or node_id == root_id or node['symbol'] in required or
                active_children[node_id]):
            continue
        remaining_symbols = {by_id[item]['symbol'] for item in retained if item != node_id}
        if not set(required).issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)
        parent = node['parent']
        if parent is not None:
            active_children[parent].remove(node_id)

    return {'removed_node_ids': removed, 'retained_node_ids': sorted(retained)}
